// Syntax that only works when Node evaluates this file as an ES module:
// import.meta, and top-level bindings named like the parameters of the
// function that wraps each module in a Meteor bundle.
import module from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const require = module.createRequire(import.meta.url);

export const url = import.meta.url;
export const filename = __filename;
export const dirname = __dirname;
export const packageName = require("./package.json").name;

export default function getDirname() {
  return __dirname;
}
